  'dir.3t': { ru: 'Виброгашение', en: 'Vibration damping', zh: '减振' , kk: 'Титрөлуді басу'},
  'dir.3x': { ru: 'Методы и устройства активного и пассивного виброгашения конструкций', en: 'Methods and devices for active and passive vibration damping of structures', zh: '结构主动与被动减振的方法和装置' , kk: 'Құрылымдардың белсенді және белсенді емес титрөлуді басу әдістері мен құрылғылары'},
  'dir.4t': { ru: 'Обследование', en: 'Inspection', zh: '检测' , kk: 'Зерттеу'},
  'dir.4x': { ru: 'Инструментальное обследование зданий и сооружений в сейсмических зонах', en: 'Instrumental inspection of buildings and structures in seismic zones', zh: '地震区建筑与结构的仪器检测' , kk: 'Сейсмикалық аймақтардағы ғимараттар мен құрылыстардың аспаптық зерттеуі'},
  'dir.5t': { ru: 'Паспортизация', en: 'Certification of facilities', zh: '登记建档' , kk: 'Паспортизациялау'},
  'dir.5x': { ru: 'Составление сейсмических паспортов объектов и территорий', en: 'Preparation of seismic passports of facilities and territories', zh: '编制设施和区域的地震登记册' , kk: 'Нысандардың және аумақтардың сейсмикалық паспорттарын құрастыру'},
  'dir.6t': { ru: 'Мониторинг', en: 'Monitoring', zh: '监测' , kk: 'Бақылау'},
  'dir.6x': { ru: 'Мониторинг состояния и безопасности. Системы непрерывного сейсмического мониторинга объектов и инфраструктуры', en: 'Condition and safety monitoring. Continuous seismic monitoring systems for facilities and infrastructure', zh: '状态与安全监测。设施和基础设施的连续地震监测系统' , kk: 'Күйі мен қауіпсіздігінің бақылауы. Нысандардың инфрақұрылымының және үздіксіз сейсмикалық бақылау жүйелері'},
  'dir.7t': { ru: 'Испытания', en: 'Testing', zh: '试验' , kk: 'Сипаттау'},
