  'dir.8t': { ru: 'Моделирование', en: 'Simulation', zh: '模拟' , kk: 'Моделдеу'},
  'dir.8x': { ru: 'Численное и физическое моделирование сейсмического отклика сооружений', en: 'Numerical and physical simulation of the seismic response of structures', zh: '结构地震响应的数值与物理模拟' , kk: 'Құрылыстардың сейсмикалық жауабының сандық және физикалық моделдеуі'},
  'dir.9t': { ru: 'Расчёты', en: 'Analysis & calculations', zh: '计算' , kk: 'Есептеулер'},
