  'dir.10t': { ru: 'Оценка рисков', en: 'Risk assessment', zh: '风险评估' , kk: 'Риск бағалауы'},
  'dir.10x': { ru: 'Оценка и управление рисками. Сейсмический риск территорий и инфраструктуры', en: 'Risk assessment and management. Seismic risk of territories and infrastructure', zh: '风险评估与管理。区域和基础设施的地震风险' , kk: 'Ристерді бағалау және басқару. Аумақтардың және инфрақұрылымның сейсмикалық қаупі'},
  'dir.11t': { ru: 'Сейсмология', en: 'Seismology', zh: '地震学' , kk: 'Сейсмология'},
