  // ===== Знак качества + товарные знаки =====
  'qual.eyebrow': { ru: 'Знак качества', en: 'Quality mark', zh: '质量标志' , kk: 'Сапас белгісі'},
  'qual.h2a': { ru: '«СейсмоБезопасность» —', en: '“Seismic Safety” —', zh: '“抗震安全”——' , kk: '«СейсмоБезопасность» —'},
  'qual.h2b': { ru: 'новый знак качества', en: 'a new quality mark', zh: '新质量标志' , kk: 'жаңа сапас белгісі'},
  'qual.lead': { ru: 'В конце 2015 года в Росстандарте был зарегистрирован новый знак качества «СейсмоБезопасность». Система добровольной сертификации разработана с участием экспертов СРОСС®.', en: 'At the end of 2015, the new “Seismic Safety” quality mark was registered with Rosstandart. The voluntary certification system was developed with the participation of SROSS® experts.', zh: '2015年底，新质量标志“抗震安全”在俄罗斯联邦技术法规与计量局注册。自愿认证系统由СРОСС®专家参与开发。' , kk: '2015 жылы аяғында Ростандаарда «СейсмоБезопасность» жаңа сапас белгісі тіркелді. Ерікті сертификаттау жүйесі СРОСС® мамандарының қатысуымен әзірленді.'},
  'qual.link': { ru: 'Читать интервью на Serconsrus.ru', en: 'Read the interview on Serconsrus.ru', zh: '在 Serconsrus.ru 上阅读采访' , kk: 'Serconsrus.ru сайтындағы сұхбатты оқу'},
  'qual.quote': { ru: '«Появление нашего значка на продукции означает её соответствие сразу 12 государственным стандартам. Поэтому добровольная сертификация в любой системе является ярким маркером качества товара».', en: '“The appearance of our mark on a product means its compliance with 12 state standards at once. Therefore, voluntary certification in any system is a bright marker of product quality.”', zh: '“我们的标志出现在产品上即意味着该产品同时符合12项国家标准。因此，任何体系中的自愿认证都是产品质量的鲜明标志。”' , kk: '«Біздің белгімізді өнімде болуы оның бір уақытта 12 мемлекеттік стандартқа сәйкес келетінін білдіреді. Сондықтан кез келген жүйедегі ерікті сертификаттау тауар сапасының айқын көрсеткіші болып табылады».'},
  'qual.quoteBy': { ru: '— Из интервью о системе «СейсмоБезопасность»', en: '— From an interview about the “Seismic Safety” system', zh: '——摘自关于“抗震安全”体系的采访' , kk: '— «СейсмоБезопасность» жүйесі туралы сұхбаттан'},
  'qual.advH': { ru: 'Ключевые преимущества знака качества', en: 'Key advantages of the quality mark', zh: '质量标志的主要优势' , kk: 'Сапас белгісінің негізгі артықшылықтары'},
  'qual.adv1': { ru: 'Соответствие сразу 12 государственным стандартам — превышает требования ГОСТ Р', en: 'Compliance with 12 state standards at once — exceeds the GOST R requirements', zh: '同时符合12项国家标准——超过GOST R的要求' , kk: 'Бір уақытта 12 мемлекеттік стандартқа сәйкестік — ГОСТ Р талаптарынан асып түседі'},
  'qual.adv2': { ru: 'Покрытие: сейсмостойкость, виброустойчивость, вибропрочность, климатические факторы', en: 'Coverage: seismic resistance, vibration stability, vibration strength, climatic factors', zh: '覆盖范围：抗震性、耐振性、振动强度、气候因素' , kk: 'Қамту: сейсмостық төзімділік, дірілге төзімділік, дірілге берік болу, климаттық факторлар'},
  'qual.adv3': { ru: 'Стоимость в 1,5 раза ниже ГОСТ Р, сроки в 2 раза быстрее', en: '1.5 times cheaper than GOST R, twice as fast', zh: '成本比GOST R低1.5倍，速度快2倍' , kk: 'Құны ГОСТ Р-дан 1,5 есе төмен, мерзімі 2 есе жылдам'},
  'qual.adv4': { ru: 'Два метода: реальные испытания (вибросейсмоплатформа) и расчётный', en: 'Two methods: real testing (vibroseismic platform) and computational', zh: '两种方法：实际试验（振动地震平台）和计算法' , kk: 'Екі әдіс: нақты сынақтар (вибросейсмоплатформа) және есептеу'},
