  // ===== Автор =====
  'auth.eyebrow': { ru: '05 · О авторе', en: '05 · About the author', zh: '05 · 关于作者' , kk: '05 · Авторы туралы'},
  'auth.h2a': { ru: 'Акбиев Рустам', en: 'Rustam Akbiev', zh: '鲁斯塔姆·阿克比耶夫' , kk: 'Құбашев Рүстем'},
  'auth.h2b': { ru: 'Тоганович', en: 'Toganovich', zh: '·托加诺维奇' , kk: 'Төңкеріұлы'},
  'auth.lead': { ru: 'Кандидат технических наук, автор 71 патента, основатель информационной системы СРОСС® и Международной научной школы «Сейсмическая безопасность сооружений и городов». Более 40 лет профессиональной деятельности в области сейсмостойкого строительства, градостроительства и оценки недвижимости.', en: 'Candidate of Technical Sciences, author of 71 patents, founder of the SROSS® information system and the International Scientific School “Seismic Safety of Structures and Cities”. More than 40 years of professional activity in seismic-resistant construction, urban development and real estate valuation.', zh: '技术科学副博士、71项专利的作者、СРОСС®信息系统和“建筑与城市地震安全”国际学派的创始人。在抗震建筑、城市规划和房地产评估领域拥有40多年的专业经验。' , kk: 'Техника ғылымдарының кандидаты, 71 патент иесі, СРОСС® ақпараттық жүйесі мен «Құрылыстар мен қалалардың сейсмобезенділігі» халықаралық ғылыми мектебінің негізін қалаушы. Сейсмоберге төзімді құрылыс, қала құрылысы және меншік құнын бағалау саласында 40-тан астам жылдық кәсіби қызмет тәжірибесі.'},
  'auth.qualsH': { ru: 'Квалификация и профессиональный стаж', en: 'Qualifications and professional experience', zh: '资历与专业工龄' , kk: 'Біліктілік және кәсіби стаж'},
